async function handleChatExport(tab: chrome.tabs.Tab, format: 'txt' | 'md' | 'json'): Promise<void> {
    // ... (Keep previous logging and logic, ensure result handling is correct) ...
    console.log(`Snaggle Popup: Initiating chat export for format: ${format}, Tab ID: ${tab.id}`); // Log initiation
    showLoading(`Exporting chat as ${format.toUpperCase()}...`);
    if (!tab.id) { showError("Tab ID missing for chat export."); return; }
    try {
        const results = await api.scripting.executeScript<[typeof format], ChatExtractionResult>({ /* ... */ });
        const injectionResult = results?.[0];
        const resultData = injectionResult?.result;
        console.log("Snaggle Popup: Chat executeScript result received:", injectionResult); // Log raw result

        if (!resultData || resultData.error) {
            console.error("Snaggle Popup: Chat script execution failed or returned error.", resultData?.error);
            throw new Error(resultData?.error || "Chat script execution failed or returned no result.");
        }
        // ... rest of success logic ...
         triggerDownload(resultData.content, sanitizeFilename(resultData.filename)); // Example simplification
        if (loadingDiv) loadingDiv.textContent = "Download started!";
        setTimeout(() => window.close(), 1500);

    } catch (error: any) {
        // Log the error caught by the popup's try/catch
        console.error("Snaggle Popup: Error in handleChatExport:", error);
        showError(`Snaggle: Chat export failed: ${error?.message ?? 'Unknown error'}`);
        if (loadingDiv) loadingDiv.hidden = true;
    }
}

