async function handleGeneralExport(tab: chrome.tabs.Tab, format: 'pdf' | 'txt' | 'md'): Promise<void> {
    // --- Added More Logging ---
    console.log(`Snaggle Popup: Initiating general export for format: ${format}, Tab ID: ${tab.id}, URL: ${tab.url}`);
    showLoading(`Exporting page as ${format.toUpperCase()}...`);
    if (!tab.id) { showError("Tab ID missing for general export."); return; }

    try {
         const pageTitle = tab.title || 'page';
         const baseFilename = sanitizeFilename(pageTitle);

         if (format === 'pdf') {
             console.log("Snaggle Popup: Requesting print dialog via script injection.");
             showLoading("Opening Print Dialog...");
             await api.scripting.executeScript({ target: { tabId: tab.id }, func: () => { window.print(); } });
             console.log("Snaggle Popup: Print dialog script injected.");
             setTimeout(() => window.close(), 500);
             return;
         } else if (format === 'txt' || format === 'md') {
             console.log(`Snaggle Popup: Injecting script to extract ${format} content...`);
             // Use wrapper func, expect PageExtractionResult
             const results: InjectionResult<PageExtractionResult>[] = await api.scripting.executeScript({
                 target: { tabId: tab.id },
                 func: (fmt) => GeneralExporter.extractPageData(fmt),
                 args: [format]
             });

             // --- Log the raw result from executeScript ---
             console.log("Snaggle Popup: General executeScript result received:", results);

             const injectionResult = results?.[0];
             const extracted = injectionResult?.result; // PageExtractionResult | null

             // --- Detailed check of the result ---
             if (!injectionResult) {
                 console.error("Snaggle Popup: executeScript returned no result array.");
                 throw new Error("General script injection failed (no result array).");
             }
              if (extracted === null) {
                 console.error("Snaggle Popup: Script execution returned null. Check target page console for errors.");
                 // Try to get more info if available on the injectionResult itself (though often not detailed)
                 const injectionError = (injectionResult as any).error;
                 throw new Error(`General script execution failed in target frame.${injectionError ? ' Info: '+injectionError : ''}`);
             }
             if (extracted.error) {
                 console.error("Snaggle Popup: Script execution returned an error property:", extracted.error);
                 throw new Error(extracted.error);
             }
             // --- End Detailed Check ---

             // Destructure from the result object (guaranteed non-null and no error property here)
             console.log("Snaggle Popup: Script execution successful, processing content.");
             let content = extracted.content;
             const requiresMarkdownConversion = extracted.requiresMarkdownConversion;

             if (format === 'md' && requiresMarkdownConversion) {
                 if (typeof TurndownService !== 'undefined') {
                     console.log("Snaggle Popup: Converting HTML to Markdown...");
                     content = GeneralExporter.convertHtmlToMarkdown(content);
                 } else { /* ... fallback log/handling ... */ }
             }
             const filename = `${baseFilename}.${format}`;
             const mimeType = format === 'txt' ? 'text/plain;charset=utf-8' : 'text/markdown;charset=utf-8';
             console.log(`Snaggle Popup: Triggering download for ${filename}`);
             triggerDownload(content, filename, mimeType);
             if (loadingDiv) loadingDiv.textContent = "Download started!";
             setTimeout(() => window.close(), 1500);
         } else {
             // Should not be reachable
             throw new Error(`Unsupported export format: ${format}`);
         }
     } catch (error: any) {
         // --- Log the specific error caught by popup's try/catch ---
         console.error("Snaggle Popup: Error in handleGeneralExport:", error);
         showError(`Snaggle: General export failed: ${error?.message ?? 'Unknown error'}`);
         if (loadingDiv) loadingDiv.hidden = true;
     }
 }

